        "They present with breathlessness, syncope, confusion, fatigue or vomiting - so any of these in a diabetic earns an ECG. [ESC 2023]",
        "Silent infarction occurs in about **a fifth of diabetics** - which is why the ECG threshold must be low in that group. [ESC 2023]",
        "Examine BP in both arms, heart rate, JVP, lung bases, murmurs and perfusion - unequal arm pressures suggest dissection, not infarction. [ESC 2023]",
