        "The threshold is **1 mm** in all leads except V2-V3 - those two leads normally sit slightly elevated. [UDMI 2018]",
        "In V2-V3 the threshold is **2 mm in men aged 40 or above** - male repolarisation gives higher baseline ST take-off. [UDMI 2018]",
        "In V2-V3 the threshold is **2.5 mm in men under 40**, and 1.5 mm in women - young men have the highest normal elevation. [UDMI 2018]",
        "New **left bundle branch block** with a compatible clinical picture is treated as STEMI - the block hides the ST segment. [ESC 2023]",
        "Sgarbossa criteria raise specificity: concordant ST elevation of **1 mm** - concordance cannot be explained by the block alone. [ESC 2023]",
        "Sgarbossa: concordant ST depression of **1 mm in V1-V3**, or discordant ST elevation of 5 mm - each scores, and any one suffices. [ESC 2023]",
        "Leads II, III and aVF: **inferior** infarct - right coronary artery in about 80%, so check V4R next. [ESC 2023]",
        "Leads V1-V4: **anterior** infarct - left anterior descending artery, the largest territory and the worst prognosis. [ESC 2023]",
