            "HFrEF leads to **eccentric hypertrophy** and dilatation - sarcomeres are added in series so a bigger cavity can eject the same volume. [Harrison 21e]",
            "Neurohormonal activation then drives progressive **remodelling** - adrenergic and angiotensin signals that help acutely are toxic chronically. [Harrison 21e]",
