            "That causes **concentric hypertrophy**, myocardial fibrosis and stiffening - a stiff wall needs a higher pressure to fill to the same volume. [Harrison 21e]",
            "Filling pressures rise steeply with **small volume changes** - the stiff ventricle sits on the steep limb of its pressure-volume curve. [Harrison 21e]",
            "HFpEF therefore decompensates on **exertion or after a salt load** - venous return rises for a few minutes and pressure spikes. [Harrison 21e]",
            "Loss of **atrial contraction** in atrial fibrillation decompensates HFpEF - atrial kick supplies up to 30% of filling in a stiff ventricle. [Harrison 21e]",
