            "HFrEF radiograph shows **cardiomegaly** - the cardiothoracic ratio exceeds 0.5 because the cavity itself has enlarged. [Harrison 21e]",
            "HFpEF: **older and more often female**, with hypertension, obesity and diabetes - decades of afterload and metabolic injury. [ESC 2021]",
