        "**Non-HDL cholesterol (total minus HDL) is the better secondary target** - it counts every apolipoprotein B particle. [Lipid Association of India 2020]",
        "**The non-HDL target is always the LDL target plus 30 mg/dL** - one arithmetic step, and frequently examined. [Lipid Association of India 2020]",
        "A non-fasting sample is acceptable for screening; **fast 9-12 hours once triglycerides exceed 400 mg/dL**. [Lipid Association of India 2020]",
        "**The Friedewald equation is invalid above 400 mg/dL** - it assumes VLDL equals triglycerides divided by 5. [Lipid Association of India 2020]",
