        "Non-HDL targets sit **30 mg/dL above** the LDL target in every one of these categories. [Lipid Association of India 2020]",
        "**Four groups need a statin with no risk score:** established ASCVD, LDL 190 mg/dL or more, diabetes aged 40-75, and CKD. [Lipid Association of India 2020]",
