        "**Bleeding history 1, labile INR 1, elderly over 65 years 1, drugs or alcohol 1 each - maximum 9.** [ESC 2024]",
        "**A HAS-BLED of 3 or more flags high bleeding risk but is never a reason to withhold anticoagulation** - the commonest examiner trap. [ESC 2024]",
        "It obliges correction of the modifiable factors: uncontrolled hypertension, labile INR, antiplatelets, NSAIDs and alcohol. [ESC 2024]",
