        "This is pre-excited atrial fibrillation in Wolff-Parkinson-White syndrome; verapamil and every other AV nodal blocking drug, including adenosine, diltiazem, digoxin and beta-blockers, preferentially block the AV node and drive conduction down the accessory pathway, which can accelerate the ventricular rate into ventricular fibrillation. Procainamide slows conduction in the accessory pathway itself and is the drug of choice when the patient is stable, and ibutilide is an accepted alternative. Magnesium is not harmful and intravenous fluids are irrelevant to the conduction problem, so neither is the answer to a question about a contraindicated drug.",
