        "**Rest pain is worse lying flat and relieved by hanging the leg out of bed** - gravity supplies the missing perfusion pressure. [AHA/ACC 2016]",
        "**Without revascularisation the amputation rate approaches 25% at one year.** [AHA/ACC 2016]",
